import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.ClgMjOt7.js";const m=JSON.parse('{"title":"テレメトリ & クラッシュハンドラー仕様","description":"GlitchTip の動的切り替えと CrashHandler 実装","frontmatter":{"title":"テレメトリ & クラッシュハンドラー仕様","description":"GlitchTip の動的切り替えと CrashHandler 実装"},"headers":[],"relativePath":"dev/telemetry-spec.md","filePath":"dev/telemetry-spec.md","lastUpdated":1790171786000}'),c={name:"dev/telemetry-spec.md"};function r(i,e,l,n,s,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="テレメトリ-クラッシュハンドラー仕様" tabindex="-1">テレメトリ &amp; クラッシュハンドラー仕様 <a class="header-anchor" href="#テレメトリ-クラッシュハンドラー仕様" aria-label="Permalink to &quot;テレメトリ &amp; クラッシュハンドラー仕様&quot;">​</a></h1><hr><h2 id="sdk-動的制御-illustiaapplication" tabindex="-1">SDK 動的制御 (<code>IllustiaApplication</code>) <a class="header-anchor" href="#sdk-動的制御-illustiaapplication" aria-label="Permalink to &quot;SDK 動的制御 (`IllustiaApplication`)&quot;">​</a></h2><p><code>AppSettings.sendTelemetry</code>（デフォルト <code>false</code>）の値に基づき、GlitchTip 互換の Sentry Android SDK を動的に開始・停止します。</p><p>SDK の ContentProvider による自動初期化は <code>AndroidManifest.xml</code> の <code>io.sentry.auto-init=false</code> で無効化されています。ユーザーが明示的にオプトインした場合に限り <code>GlitchTipTelemetry</code> が SDK を初期化し、オプトアウト時は直ちに停止します。</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GlitchTipTelemetry.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(applicationContext, settings.sendTelemetry)</span></span></code></pre></div><p>GlitchTip の DSN は <code>AndroidManifest.xml</code> に設定し、パフォーマンストレースはオプトイン時に 100%（<code>1.0</code>）サンプリングされます。GlitchTip が非対応の自動セッション追跡、既定 PII、Frame Metrics エンベロープは無効化されています。</p><hr><h2 id="ローカルクラッシュハンドラー-未捕獲例外送信-crashhandler" tabindex="-1">ローカルクラッシュハンドラー &amp; 未捕獲例外送信 (<code>CrashHandler</code>) <a class="header-anchor" href="#ローカルクラッシュハンドラー-未捕獲例外送信-crashhandler" aria-label="Permalink to &quot;ローカルクラッシュハンドラー &amp; 未捕獲例外送信 (`CrashHandler`)&quot;">​</a></h2><p><code>Thread.UncaughtExceptionHandler</code> を継承し、未捕獲例外発生時に以下の処理を行います：</p><ol><li>スタックトレースを解析し、リソース未検出 (<code>Resources.NotFoundException</code>) やドキュメントアクセス権限エラーを検知して復旧ダイアログ/トーストを表示。</li><li>テレメトリ有効時、<code>GlitchTipTelemetry.recordException(ex, tag = &quot;uncaught_crash&quot;)</code> によりクラッシュレポートを送信し、<code>GlitchTipTelemetry.flush()</code> でプロセス終了前に確実にフラッシュ。</li></ol><hr><h2 id="非致命的例外-non-fatal-exceptions-の集約" tabindex="-1">非致命的例外（Non-fatal Exceptions）の集約 <a class="header-anchor" href="#非致命的例外-non-fatal-exceptions-の集約" aria-label="Permalink to &quot;非致命的例外（Non-fatal Exceptions）の集約&quot;">​</a></h2><p>各種 ViewModel、フィード読み込み、検索、詳細表示、ブックマーク、ダウンロード、PallaSync 同期処理などで発生した予期せぬ例外を <code>GlitchTipTelemetry.recordException(...)</code> で収集します。</p><ul><li><code>CancellationException</code>（コルーチンキャンセル）は自動的に除外されます。</li><li>モジュールタグ（<code>module</code>）および追加コンテキスト情報（クエリ、URL、作品IDなど）を付与して記録されます。</li></ul><hr><h2 id="パフォーマンストレース" tabindex="-1">パフォーマンストレース <a class="header-anchor" href="#パフォーマンストレース" aria-label="Permalink to &quot;パフォーマンストレース&quot;">​</a></h2><p>GlitchTip は Sentry Envelope の <code>transaction</code> アイテムタイプを受け入れるため、Sentry Android SDK のパフォーマンス計測機能をそのまま利用できます。</p><h3 id="サンプリングレート" tabindex="-1">サンプリングレート <a class="header-anchor" href="#サンプリングレート" aria-label="Permalink to &quot;サンプリングレート&quot;">​</a></h3><p><code>AndroidManifest.xml</code> の <code>io.sentry.traces.sample-rate = 1.0</code>（100%）。</p><h3 id="計測トランザクション" tabindex="-1">計測トランザクション <a class="header-anchor" href="#計測トランザクション" aria-label="Permalink to &quot;計測トランザクション&quot;">​</a></h3><table tabindex="0"><thead><tr><th>トランザクション名</th><th>operation</th><th>計測範囲 / 説明</th></tr></thead><tbody><tr><td><code>app.startup</code></td><td><code>app.launch</code></td><td><code>IllustiaApplication.onCreate()</code> 内でテレメトリ有効化完了 〜 <code>startPostStartupWork()</code> 末尾</td></tr><tr><td><code>feed.home.load</code> / <code>feed.home.refresh</code></td><td><code>feed.home</code></td><td>ホームフィードの取得・復元・キャッシュ</td></tr><tr><td><code>feed.home.load_more</code></td><td><code>feed.home</code></td><td>ホームフィードの追加ページ取得</td></tr><tr><td><code>feed.ranking.refresh</code></td><td><code>feed.ranking</code></td><td>ランキング一覧の取得・更新</td></tr><tr><td><code>feed.ranking.load_more</code></td><td><code>feed.ranking</code></td><td>ランキング一覧の追加ページ取得</td></tr><tr><td><code>feed.timeline.refresh</code></td><td><code>feed.timeline</code></td><td>フォロー新着タイムラインの取得・更新</td></tr><tr><td><code>feed.timeline.load_more</code></td><td><code>feed.timeline</code></td><td>フォロー新着タイムラインの追加ページ取得</td></tr><tr><td><code>feed.watchlist.refresh</code></td><td><code>feed.watchlist</code></td><td>ウォッチリスト（タグ）の検索・取得</td></tr><tr><td><code>feed.watchlist.load_more</code></td><td><code>feed.watchlist</code></td><td>ウォッチリスト（タグ）の追加ページ取得</td></tr><tr><td><code>feed.novels.refresh</code></td><td><code>feed.novels</code></td><td>小説フィードの取得・更新</td></tr><tr><td><code>search.query</code></td><td><code>search</code></td><td>イラスト・マンガ・小説・ユーザーの複合検索</td></tr><tr><td><code>illust.detail.load</code></td><td><code>illust.detail</code></td><td>作品詳細、関連作品、コメント、投稿者情報の並行取得</td></tr><tr><td><code>user.profile.load</code></td><td><code>user.profile</code></td><td>ユーザー詳細プロファイルおよび投稿作品の並行取得</td></tr><tr><td><code>bookmarks.refresh</code> / <code>bookmarks.load_more</code></td><td><code>bookmarks</code></td><td>ブックマーク一覧の取得・追加読み込み</td></tr><tr><td><code>download.artwork</code></td><td><code>download</code></td><td>通常イラスト・マンガ画像の保存</td></tr><tr><td><code>ugoira.convert.gif</code></td><td><code>ugoira.convert</code></td><td>うごイラフレームの GIF エンコード処理</td></tr><tr><td><code>ugoira.convert.mp4</code></td><td><code>ugoira.convert</code></td><td>うごイラフレームの MP4 エンコード処理</td></tr><tr><td><code>pallasync.sync</code></td><td><code>sync.operation</code></td><td>PallaSync デバイス同期、アウトボックス送信、インボックス受信</td></tr></tbody></table><p><code>GlitchTipTelemetry.trace</code> / <code>GlitchTipTelemetry.traceAsync</code> はテレメトリが無効な場合に計測オーバーヘッドなしでブロックを直接実行するため、呼び出し側で同意状態を別途確認する必要はありません。</p><h3 id="glitchtip-非対応のため無効化している機能" tabindex="-1">GlitchTip 非対応のため無効化している機能 <a class="header-anchor" href="#glitchtip-非対応のため無効化している機能" aria-label="Permalink to &quot;GlitchTip 非対応のため無効化している機能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>オプション</th><th>理由</th></tr></thead><tbody><tr><td><code>isEnableFramesTracking = false</code></td><td>GlitchTip が Frame Metrics エンベロープを処理しない</td></tr><tr><td><code>isEnablePerformanceV2 = false</code></td><td>Sentry 固有の拡張 API で GlitchTip 未対応</td></tr><tr><td><code>isEnableAutoSessionTracking = false</code></td><td>セッション追跡は GlitchTip 非対応</td></tr></tbody></table>',25)])])}const f=t(c,[["render",r]]);export{m as __pageData,f as default};
